import math

def factorize(num):
    factors = []
    temp = num
    p = 2
    while p * p <= temp:
        if temp % p == 0:
            count = 0
            while temp % p == 0:
                count += 1
                temp //= p
            factors.append((p, count))
        p += 1
    if temp > 1:
        factors.append((temp, 1))
    return factors

def is_valid(cur, factors_k):
    for j in range(len(factors_k)):
        if cur[j] < factors_k[j][1]:
            return False
    return True

def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    if k == 1:
        total = n * (n+1) // 2
        print(total)
        return

    factors_k = factorize(k)
    m = len(factors_k)

    exp_vecs = []
    for num in a:
        vec = [0] * m
        for idx, (p, req) in enumerate(factors_k):
            cnt = 0
            temp_num = num
            while temp_num % p == 0:
                cnt += 1
                temp_num //= p
            vec[idx] = cnt
        exp_vecs.append(vec)

    cur = [0] * m
    left = 0
    right = -1
    count_valid = 0

    for left in range(n):
        while right < n-1 and not is_valid(cur, factors_k):
            right += 1
            for j in range(m):
                cur[j] += exp_vecs[right][j]

        if is_valid(cur, factors_k):
            count_valid += (n - right)

        for j in range(m):
            cur[j] -= exp_vecs[left][j]

    print(count_valid)

