    if n == 0:
        return ""
    first_digit = int(target[0])
    for d in range(9, -1, -1):
        if freq[d] == 0:
            continue
        if d > first_digit:
            continue
        new_freq = freq.copy()
        new_freq[d] -= 1
        if d < first_digit:
            rest = []
            for digit in range(9, -1, -1):
                rest.append(str(digit) * new_freq[digit])
            return str(d) + ''.join(rest)
        else:
            res = find(new_freq, target[1:])
            if res is not None:
                return str(d) + res
    return None

